function ParseNestedParens(parenString : string): array of integer;
begin
  var maxLevel := 0;
  var currentLevel := 0;
  var stack := new Stack<integer>;
  var resultList := new List<integer>;
  var chars := parenString.ToCharArray;

  for var i := 1 to chars.Length do
  begin
    if chars[i] = '(' then
    begin
      currentLevel += 1;
      if currentLevel > maxLevel then
        maxLevel := currentLevel;
      stack.Push(currentLevel);
    end
    else if chars[i] = ')' then
    begin
      currentLevel -= 1;
      stack.Pop;
    end;
  end;

  for var i := 0 to maxLevel - 1 do
    resultList.Add(i);

  Result := resultList.ToArray;
end;


