function FindClosestElements(numbers: array of real): (real, real);
begin
  var sorted := numbers.OrderBy(x -> x).ToArray;
  var minDiff := real.MaxValue;
  var closest := (real.MaxValue, real.MaxValue);

  for var i := 0 to sorted.Length - 2 do
  begin
    var diff := sorted[i + 1] - sorted[i];
    if diff < minDiff then
    begin
      minDiff := diff;
      closest := (sorted[i], sorted[i + 1]);
    end;
  end;

  Result := closest;
end;


