  if evenList.Length = 0 then
  begin
    Result := new integer[0];
    exit;
  end;
  var smallestEven := evenList.Min;
  var smallestIndex := evenList.IndexOf(smallestEven);
  Result := new integer[2];
  Result[0] := smallestEven;
  Result[1] := smallestIndex;
end;


function Search(lst: array of integer): integer;
begin
  var count := new Dictionary<integer, integer>;
  foreach var num in lst do
    if count.ContainsKey(num) then
      count[num] += 1
    else
      count.Add(num, 1);
  var maxFreq := count.Values.Max;
  var res := -1;
  foreach var kv in count do
    if kv.Value = maxFreq then
    begin
      res := kv.Key;
      break;
    end;
