function Multiply(a, b : integer): integer;
begin
  var product := 0;
  var aDigits := Abs(a);
  var bDigits := Abs(b);
  var aDigit := 0;
  var bDigit := 0;
  var carry := 0;

  for var i := 1 to aDigits do
  begin
    aDigit := aDigits mod 10;
    aDigits := aDigits div 10;

    for var j := 1 to bDigits do
    begin
      bDigit := bDigits mod 10;
      bDigits := bDigits div 10;

      var tempProduct := aDigit * bDigit + carry;
      carry := tempProduct div 10;
      product := product + (tempProduct mod 10);
    end;

    if carry > 0 then
      product := product + carry;
  end;

  Result := product;
end;


