  var count := 0;

  for var i := 0 to m - 1 do
    for var j := 0 to n - 1 do
    begin
      if grid[i, j] = 1 then
      begin
        var k := i;
        while (k > 0) and (buckets[k, j] = 1) do
          k -= 1;
        if (k <> 0) and (buckets[k, j] = 0) and (buckets[k - 1, j] < capacity) then
        begin
          buckets[k, j] := 1;
          count += 1;
        end;
      end;
    end;

  Result := count;
end;


