function ProdSigns(arr: array of integer): integer;
begin
  if arr.Length = 0 then
  begin
    Result := 0;
    exit;
  end;

  var sign := 1;
  var product := 1;
  var sum := 0;

  foreach var num in arr do
  begin
    if num = 0 then
    begin
      Result := 0;
      exit;
    end;

    sign := sign * (num > 0) - (num < 0);
    product := product * Abs(num);
    sum := sum + Abs(num);
  end;

  Result := sign * product * sum;
end;


function Minpath(grid : array of array of integer; k : integer): array of integer;
begin
  var n := grid.Length;
  var res := new List<integer>;
  var visited := new HashSet<(integer, integer)>;
  var directions := new List<(integer, integer)>;
  for var i := 0 to n - 1 do
    for var j := 0 to n - 1 do
      if (i = 0) or (j = 0) or (i = n - 1) or (j = n - 1) then
        directions.Add((i, j));
  var queue := new Queue<(integer, integer, integer)>;
  foreach var dir in directions do
    queue.Enqueue((grid[dir.Item1][dir.Item2], dir.Item1, dir.Item2));
  while queue.Count > 0 do
  begin
    var (val, x, y) := queue.Dequeue;
    if visited.Contains((x, y)) then
      continue;
    res.Add(val);
    visited.Add((x, y));
    if res.Count = k then
      break;
    var (dx, dy) := (0, 0);
    if x > 0 then
      dx := -1;
    if y > 0 then
      dy := -1;
    if x < n - 1 then
      dx := 1;
    if y < n - 1 then
      dy := 1;
    foreach var dir in directions do
      if (dir.Item1 = x + dx) and (dir.Item2 = y + dy) then
        queue.Enqueue((grid[dir.Item1][dir.Item2], dir.Item1, dir.Item2));
  end;
  Result := res.ToArray;
end;


function Tri(n: integer): array of real;
begin
  var tri := new real[n + 1];
  tri[0] := 3;
  for var i := 1 to n do
  begin
    if i mod 2 = 0 then
      tri[i] := tri[i - 1] + tri[i - 2] + i div 2
    else
      tri[i] := tri[i - 1] + tri[i - 2] + tri[i - 3] + i;
  end;
  Result := tri;
end;


function Digits(n: integer): integer;
begin
  var product := 1;
  var oddDigits := 0;
  var num := n;

  while num > 0 do
  begin
    var digit := num mod 10;
    if digit mod 2 <> 0 then
      oddDigits += digit;
    product *= digit;
    num := num div 10;
  end;

  Result := oddDigits;
end;


function IsNested(s: string): boolean;
begin
  var stack := new Stack<char>;
  foreach var ch in s do
  begin
    if ch = '[' then
      stack.Push(ch)
    else if ch = ']' then
    begin
      if stack.Count = 0 then
      begin
        Result := False;
        exit;
      end;
      stack.Pop;
    end;
  end;
  Result := stack.Count = 0;
end;


