  while i * i <= n do
  begin
    if n mod i = 0 then
    begin
      if (i mod 2 = 0) and (i * (n div i) = n) then
        count += 1;
      if (n div i) mod 2 = 0 then
        count += 1;
    end;
    i += 1;
  end;

  Result := count = 4;
end;


