function WordsInSentence(sentence: string): string;
begin
  var words := sentence.Split(' ');
  var primeWords := new List<string>;

  foreach var word in words do
  begin
    if word.Length > 1 then
    begin
      var isPrime := True;
      for var i := 2 to Trunc(Sqrt(word.Length)) do
        if word.Length mod i = 0 then
        begin
          isPrime := False;
          break;
        end;

      if isPrime then
        primeWords.Add(word);
    end;
  end;

  var primeWordsStr := string.Join(' ', primeWords);
  Result := primeWordsStr;
end;


