function StrongestExtension(className : string; extensions : array of string): string;
begin
  var maxStrength := -1;
  var strongestExtension := '';

  foreach var extension in extensions do
  begin
    var uppercaseCount := extension.Count(c -> Char.IsUpper(c));
    var lowercaseCount := extension.Count(c -> Char.IsLower(c));
    var strength := uppercaseCount - lowercaseCount;

    if (strength > maxStrength) or (strength = maxStrength) and (extension < strongestExtension) then
    begin
      maxStrength := strength;
      strongestExtension := extension;
    end;
  end;

  Result := className + '.' + strongestExtension;
end;


