function FindMax(words : array of string): string;
begin
  var maxUnique := 0;
  var maxWord := '';

  foreach var word in words do
  begin
    var uniqueCount := word.Distinct.Count;
    if uniqueCount > maxUnique then
    begin
      maxUnique := uniqueCount;
      maxWord := word;
    end;
  end;

  Result := maxWord;
end;


function Eat(number, need, remaining : integer): (integer, integer);
begin
  if (number + need) > remaining then
    Result := (remaining, remaining - number)
  else
    Result := (number + need, 0);
end;


function DoAlgebra(op: array of string; operand: array of integer): integer;
begin
  var res := operand[0];
  for var i := 1 to operand.Length - 1 do
  begin
    case op[i-1] of
      '+': res += operand[i];
      '-': res -= operand[i];
      '*': res *= operand[i];
      '//': res := res div operand[i];
      '**': res := Round(Power(res, operand[i]));
    end;
  end;
  Result := res;
end;


function Solve(s: string): string;
begin
  var sb := new StringBuilder;
  var isLetter := false;
  foreach var ch in s do
  begin
    if char.IsLetter(ch) then
    begin
      isLetter := true;
      if char.IsLower(ch) then
        sb.Append(char.ToUpper(ch))
      else
        sb.Append(char.ToLower(ch));
    end
    else
    begin
      isLetter := false;
      sb.Append(ch);
    end;
  end;
  if not isLetter then
    sb.Reverse;
  Result := sb.ToString;
end;


function StringToMd5(text : string): string;
begin
  if text = '' then
  begin
    Result := nil;
    exit;
  end;
  var md5 := new System.Security.Cryptography.MD5CryptoServiceProvider;
  var data := System.Text.Encoding.UTF8.GetBytes(text);
  var hash := md5.ComputeHash(data);
  Result := string.Join('', hash.Select(b -> b.ToString('x2')));
end;


